parameters.jsCode:
/**
 * n8n Code node — Readability scoring (textstat equivalent, pure JavaScript)
 * ---------------------------------------------------------------------------
 * Mode: "Run Once for All Items"
 * Input : each item must have a text field (default: item.json.text)
 * Output: original item + `readability` object
 *
 * No npm packages required. Works on n8n Cloud and self-hosted.
 *
 * Metrics: Flesch-Kincaid Grade, Flesch Reading Ease, Gunning Fog, SMOG,
 *          Coleman-Liau, Automated Readability Index, plus a plain-language
 *          check (long sentences, passive voice hints, clinical jargon).
 */

// ─────────────────────────── CONFIG ───────────────────────────
const TEXT_FIELD      = 'output';   // field on item.json holding the text
const TARGET_GRADE    = 7;        // pass if FK grade <= this
const MAX_SENTENCE_LEN = 15;      // words per sentence cap

// Clinical shorthand that should never survive a patient-facing rewrite.
const JARGON = [
  'BID','TID','QID','QD','QHS','PRN','PO','IV','IM','SC','SL','NPO','STAT',
  'NTG','AP','MI','COPD','CHF','CVA','DVT','PE','UTI','HbA1c','Dx','Tx','Rx',
  'F/U','SOB','NKDA','WNL','hypertension','hyperlipidemia','myocardial',
  'infarction','dyspnea','syncope','melena','hematemesis','cholelithiasis',
  'hyperplasia','exacerbation','sublingual','analgesia','edema','febrile',
  'prophylaxis','contraindicated','titrate','ambulate','void','afebrile'
];

// ──────────────────────── TOKENISERS ──────────────────────────

function splitSentences(text) {
  let t = ' ' + text.replace(/\s+/g, ' ').trim() + ' ';

  // Protect things that look like sentence ends but are not.
  t = t.replace(/(\d)\.(\d)/g, '$1<DEC>$2');                      // 38.5, 8.2%
  t = t.replace(/\b(Dr|Mr|Mrs|Ms|Prof|St|vs|etc|approx|Inc|Ltd|No)\./gi, '$1<ABB>');
  t = t.replace(/\b(e\.g|i\.e|a\.m|p\.m|q\.d|b\.i\.d|t\.i\.d)\./gi, '$1<ABB>');

  const parts = t.split(/(?<=[.!?…])\s+|\n+/);

  return parts
    .map(s => s.replace(/<DEC>/g, '.').replace(/<ABB>/g, '.').trim())
    .filter(s => /[A-Za-z]/.test(s));
}

function splitWords(text) {
  return (text.match(/[A-Za-z0-9][A-Za-z0-9'’\-]*/g) || []);
}

// ─────────────────────── SYLLABLE COUNT ───────────────────────
// Heuristic approximation of pyphen (what Python textstat uses).
// Expect ±0.3–0.8 grade levels of drift on short texts.

const SYLLABLE_EXCEPTIONS = {
  simile: 3, forever: 3, shoreline: 2, business: 2, wednesday: 2,
  every: 2, different: 3, medicine: 3, area: 3, idea: 3, being: 2,
  science: 2, quiet: 2, diet: 2, create: 2, people: 2, little: 2,
  our: 1, hour: 1, fire: 2, hire: 1, sure: 1, pure: 1
};

function countSyllables(word) {
  let w = word.toLowerCase().replace(/[^a-z]/g, '');
  if (!w) return 0;
  if (SYLLABLE_EXCEPTIONS[w]) return SYLLABLE_EXCEPTIONS[w];
  if (w.length <= 3) return 1;

  // Silent endings
  w = w.replace(/(?:[^laeiouy]es|[^laeiouy]e)$/, '');
  w = w.replace(/^y/, '');

  const groups = w.match(/[aeiouy]{1,2}/g);
  let n = groups ? groups.length : 0;

  // Consonant + "le" is its own syllable: candle, table, little
  if (/[^aeiouy]le$/.test(word.toLowerCase())) n += 1;
  // Common suffixes that add a beat
  if (/(?:ia|io|ua|uo|eo)/.test(w)) n += 0; // already caught by 2-vowel groups
  if (/tion$|sion$/.test(word.toLowerCase())) n = Math.max(n, 2);

  return Math.max(1, n);
}

// ───────────────────────── ANALYSIS ───────────────────────────

function analyse(rawText) {
  const text = String(rawText || '').trim();
  if (!text) {
    return { error: 'Empty text', word_count: 0 };
  }

  const sentences = splitSentences(text);
  const words     = splitWords(text);

  const nSentences = Math.max(1, sentences.length);
  const nWords     = Math.max(1, words.length);

  let nSyllables = 0;
  let nPoly      = 0;   // 3+ syllables
  let nComplex   = 0;   // 3+ syllables, excluding common suffix inflections
  let nLetters   = 0;

  for (const w of words) {
    const syl = countSyllables(w);
    nSyllables += syl;
    nLetters   += w.replace(/[^A-Za-z0-9]/g, '').length;
    if (syl >= 3) {
      nPoly++;
      if (!/(?:es|ed|ing)$/i.test(w)) nComplex++;
    }
  }

  const wps = nWords / nSentences;      // words per sentence
  const spw = nSyllables / nWords;      // syllables per word
  const L   = (nLetters / nWords) * 100;
  const S   = (nSentences / nWords) * 100;

  const round = (x, d = 1) => Math.round(x * 10 ** d) / 10 ** d;

  const fkGrade      = 0.39 * wps + 11.8 * spw - 15.59;
  const readingEase  = 206.835 - 1.015 * wps - 84.6 * spw;
  const gunningFog   = 0.4 * (wps + 100 * (nComplex / nWords));
  const smog         = 1.0430 * Math.sqrt(nPoly * (30 / nSentences)) + 3.1291;
  const colemanLiau  = 0.0588 * L - 0.296 * S - 15.8;
  const ari          = 4.71 * (nLetters / nWords) + 0.5 * wps - 21.43;

  // Plain-language checks
  const longSentences = sentences
    .map((s, i) => ({ index: i + 1, words: splitWords(s).length, text: s }))
    .filter(s => s.words > MAX_SENTENCE_LEN);

  const jargonFound = [...new Set(
    JARGON.filter(term =>
      new RegExp(`(^|[^A-Za-z])${term.replace(/[/.]/g, '\\$&')}([^A-Za-z]|$)`, 'i').test(text)
    )
  )];

  const passiveHits = (text.match(
    /\b(?:is|are|was|were|be|been|being)\s+\w+(?:ed|en)\b/gi
  ) || []);

  const grades = [fkGrade, gunningFog, smog, colemanLiau, ari];
  const consensus = grades.reduce((a, b) => a + b, 0) / grades.length;

  return {
    // Core metrics
    flesch_kincaid_grade:      round(fkGrade),
    flesch_reading_ease:       round(readingEase),
    gunning_fog:               round(gunningFog),
    smog_index:                round(smog),
    coleman_liau_index:        round(colemanLiau),
    automated_readability_index: round(ari),
    consensus_grade:           round(consensus),

    // Counts
    sentence_count:   nSentences,
    word_count:       nWords,
    syllable_count:   nSyllables,
    polysyllable_count: nPoly,
    avg_words_per_sentence: round(wps, 2),
    avg_syllables_per_word: round(spw, 2),
    reading_time_seconds: round((nWords / 200) * 60, 0),

    // Verdict against the session's target
    target_grade: TARGET_GRADE,
    passes_target: fkGrade <= TARGET_GRADE,

    // Plain-language flags
    long_sentence_count: longSentences.length,
    long_sentences: longSentences.slice(0, 10),
    jargon_found: jargonFound,
    passive_voice_hits: passiveHits.slice(0, 10),

    verdict:
      fkGrade <= TARGET_GRADE && jargonFound.length === 0 && longSentences.length === 0
        ? 'READY_FOR_CLINICIAN_REVIEW'
        : 'NEEDS_REWRITE'
  };
}

// ────────────────────── n8n ENTRY POINT ───────────────────────

return items.map(item => {
  const text = item.json[TEXT_FIELD];
  return {
    json: {
      ...item.json,
      readability: analyse(text)
    }
  };
});

